    def minDifference(self, nums: List[int]) -> int:
        n = len(nums)
        base = 0
        neighbors = []
        for i in range(n - 1):
            a, b = nums[i], nums[i + 1]
            if a != -1 and b != -1:
                base = max(base, abs(a - b))
            elif a != -1:
                neighbors.append(a)
            elif b != -1:
                neighbors.append(b)
        if not neighbors:
            return base
        lo, hi = min(neighbors), max(neighbors)
        segments = []
        i = 0
        while i < n:
            if nums[i] != -1:
                i += 1
                continue
            j = i
            while j < n and nums[j] == -1:
                j += 1
            left = nums[i - 1] if i > 0 else None
            right = nums[j] if j < n else None
            segments.append((left, right, j - i))
            i = j

        def feasible(d):
            x, y = lo + d, hi - d
            for left, right, length in segments:
                ends = [v for v in (left, right) if v is not None]
                options = [{c for c in (x, y) if abs(v - c) <= d} for v in ends]
                if any(not opt for opt in options):
                    return False
                if len(options) == 2 and not (options[0] & options[1]):
                    if length == 1 or y - x > d:
                        return False
            return True

        low, high = base, max(base, hi - lo)
        while low < high:
            mid = (low + high) // 2
            if feasible(mid):
                high = mid
            else:
                low = mid + 1
        return low

